package com.multichat.member.controller;
import com.multichat.common.api.ApiResponse; import com.multichat.infrastructure.mapper.RoomMembershipMapper; import com.multichat.member.entity.RoomMembership; import com.multichat.permission.PermissionService; import com.multichat.room.dto.RoomPage; import com.multichat.websocket.RoomSubscriptionAuthorizer; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/rooms/{roomId}/members")
public class RoomMemberController { private final RoomMembershipMapper mapper; private final PermissionService permissions; private final RoomSubscriptionAuthorizer authorizer;
 public RoomMemberController(RoomMembershipMapper mapper, PermissionService permissions, RoomSubscriptionAuthorizer authorizer){this.mapper=mapper;this.permissions=permissions;this.authorizer=authorizer;}
 @GetMapping public ResponseEntity<ApiResponse<RoomPage<RoomMembership>>> list(@PathVariable UUID roomId,@RequestParam(defaultValue="ACTIVE") String memberStatus,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="50") int limit){authorizer.requireSubscribable(permissions.currentActorId(),roomId); var rows=mapper.findByRoom(roomId,memberStatus,limit+1,(page-1)*limit); boolean more=rows.size()>limit; return ResponseEntity.ok(ApiResponse.success(new RoomPage<>(more?rows.subList(0,limit):rows,page,limit,more)));}}
